// An alternate PayPal driver behind the same interface as server/paypal.js (createOrder, getOrder, captureOrder, refundCapture), built on PayPal's own server SDK
// (@paypal/paypal-server-sdk 2.5.0, MIT; every source file in it says "automatically generated by APIMATIC v3.0"; it runs on the @apimatic/* runtime packages).
// Chosen with VESPR_PAYPAL_DRIVER=sdk; the hand-written fetch client (server/paypal.js) stays the default until this path has passed the same checks on the real sandbox
// (scripts/paypal-smoke.mjs --driver sdk). Same rules as the fetch client: sandbox only (the SDK's Environment.Sandbox; live needs VESPR_PAYPAL_LIVE=1), amounts as
// validated decimal strings, PayPal-Request-Id on create, capture and refund, credentials from the environment and never logged, the same error codes (failureFor).
// Nothing of APIMatic's Context Plugin is used: only the SDK as a library.
import { loadResult } from '@apimatic/core' // the SDK's own runtime: it fills an error's `result` from the response body, which is not done until asked
import { Client, Environment, OrdersController, PaymentsController, ApiError, CheckoutPaymentIntent } from '@paypal/paypal-server-sdk'
import { PayPalError, NOT_SET_UP, SANDBOX_BASE, LIVE_BASE, centsToValue, failureFor, checkOrderInput, checkId, cleanText, payerLinkOf, isPayPalHost } from './paypal.js'

// the SDK answers in camelCase; this is the same flat summary the fetch client returns
const summarize = o => {
  const pu = (o.purchaseUnits && o.purchaseUnits[0]) || {}; const cap = pu.payments && pu.payments.captures && pu.payments.captures[0]
  const amt = pu.amount || (cap && cap.amount) || {}
  return { id: o.id, status: o.status, value: amt.value, currency: amt.currencyCode, customId: pu.customId || (cap && cap.customId) || '', referenceId: pu.referenceId || '', captureId: cap ? cap.id : '', captureStatus: cap ? cap.status : '' }
}

export function createSdkPayPal ({
  clientId = process.env.PAYPAL_CLIENT_ID, clientSecret = process.env.PAYPAL_CLIENT_SECRET, allowLive = process.env.VESPR_PAYPAL_LIVE === '1',
  transport = null, // tests only: an axios adapter (config) => response, so no network is used (see server/test/paypal-sdk.test.js)
  log = m => console.error(m), timeoutMs = 20000
} = {}) {
  const configured = Boolean(clientId && clientSecret)
  const live = allowLive && process.env.PAYPAL_API_BASE === LIVE_BASE
  const guard = () => { if (!configured) throw new PayPalError('not_set_up', NOT_SET_UP) }
  let orders = null; let payments = null
  const ctl = () => {
    if (!orders) {
      const client = new Client({ clientCredentialsAuthCredentials: { oAuthClientId: clientId, oAuthClientSecret: clientSecret }, environment: live ? Environment.Production : Environment.Sandbox, timeout: timeoutMs, ...(transport ? { unstable_httpClientOptions: { adapter: transport } } : {}) })
      orders = new OrdersController(client); payments = new PaymentsController(client)
    }
    return { orders, payments }
  }
  // the SDK throws its own errors; they become the same PayPalError codes the payment flow already handles. Nothing of the request or the credentials is put in a message.
  const run = async (what, fn) => {
    try { return (await fn()).result } catch (e) {
      if (e instanceof PayPalError) throw e
      if (e instanceof ApiError) {
        try { await loadResult(e) } catch { /* no readable body: the status alone decides */ }
        const r = e.result || {}; const issue = cleanText((r.details && r.details[0] && r.details[0].issue) || r.name || '', 60); const debugId = cleanText(r.debug_id || r.debugId, 40)
        log(`paypal(sdk): ${what} failed (HTTP ${e.statusCode}${issue ? ', ' + issue : ''}${debugId ? ', debug_id ' + debugId : ''})`)
        throw failureFor(e.statusCode, issue, debugId)
      }
      log(`paypal(sdk): ${what} failed (${cleanText(e && e.code, 30) || 'network'})`)
      throw new PayPalError('network', 'Could not reach PayPal.')
    }
  }

  return {
    configured, mode: live ? 'live' : 'sandbox', baseUrl: live ? LIVE_BASE : SANDBOX_BASE, driver: 'sdk',

    async createOrder ({ requestId, cents, currency = 'USD', description = '', referenceId, customId, returnUrl, cancelUrl, brandName = 'VESPR' } = {}) {
      guard(); checkOrderInput({ requestId, cents, currency, returnUrl, cancelUrl })
      const body = {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [{ referenceId: cleanText(referenceId || requestId, 256), customId: cleanText(customId || requestId, 255), description: cleanText(description, 127), amount: { currencyCode: currency, value: centsToValue(cents) } }],
        paymentSource: { paypal: { experienceContext: { brandName: cleanText(brandName, 127), shippingPreference: 'NO_SHIPPING', landingPage: 'LOGIN', userAction: 'PAY_NOW', paymentMethodPreference: 'IMMEDIATE_PAYMENT_REQUIRED', returnUrl, cancelUrl } } }
      }
      const o = await run('create order', () => ctl().orders.createOrder({ body, paypalRequestId: requestId }))
      const approveUrl = payerLinkOf(o.links)
      if (!o.id || !approveUrl) { log('paypal(sdk): the order answer had no id or payer link'); throw new PayPalError('bad_response', 'PayPal answered in a way this server does not understand; nothing was charged.') }
      if (!transport && !isPayPalHost(approveUrl)) { log('paypal(sdk): the payer link was not on paypal.com; refused'); throw new PayPalError('bad_response', 'PayPal gave an unexpected link; it was not used.') }
      return { id: o.id, status: o.status, approveUrl }
    },

    async getOrder (id) { guard(); checkId(id); return summarize(await run('get order', () => ctl().orders.getOrder({ id }))) },

    async captureOrder (id, { requestId } = {}) {
      guard(); checkId(id)
      return summarize(await run('capture order', () => ctl().orders.captureOrder({ id, ...(requestId ? { paypalRequestId: requestId } : {}) })))
    },

    async refundCapture (captureId, { requestId, cents, currency = 'USD', note = '' } = {}) {
      guard(); checkId(captureId, 'capture')
      if (!Number.isInteger(cents) || cents <= 0) throw new PayPalError('bad_request', 'The refund amount must be a positive number of cents.')
      if (!/^[A-Z]{3}$/.test(String(currency))) throw new PayPalError('bad_request', 'The currency must be a three-letter code.')
      const body = { amount: { currencyCode: currency, value: centsToValue(cents) }, ...(cleanText(note, 255) ? { noteToPayer: cleanText(note, 255) } : {}) }
      const f = await run('refund', () => ctl().payments.refundCapturedPayment({ captureId, body, ...(requestId ? { paypalRequestId: requestId } : {}) }))
      if (!f.id || !['COMPLETED', 'PENDING', 'FAILED', 'CANCELLED'].includes(f.status)) throw new PayPalError('bad_response', 'PayPal answered the refund in a way this server does not understand.')
      return { id: f.id, status: f.status }
    }
  }
}
